mapper.select:
SELECT u.id, u.username, u.image_url, u.email, u.phone, u.status, r.role_name, u.create_time, FROM user u INNER JOIN user_role ur ON u.id = ur.user_id INNER JOIN role r ON ur.role_id = r.id WHERE
AND u.id = #{condition.id}
AND u.username LIKE CONCAT('%', #{condition.username}, '%')
AND u.email = #{condition.email}
AND u.status = #{condition.status}
ORDER BY u.create_time DESC
